exec(open("batches/hiv_common.py").read())
# HIV 2022 part 1, pp.42-46 (PrEP initiation and follow-up, PEP). Cell text from the PDF ruled grid, layout checked on the page images.
C2 = "Chapter 2: Prevention of HIV"
ITEMS = [
 T("tbl-2.4-prep-initiation-visit", 42, C2 + " > 2.5 Pre-exposure Prophylaxis > PrEP Initiation visit > Table 2.4 components of the PrEP initiation visit", "Table 2.4 Components of the PrEP initiation visit", ["0080", "0081"],
   [r("Component", "Action")],
   [r(a, b) for a, b in [["HIV testing and counselling", "• If the clients test positive, the client should be initiated on/ referred for ART.<br/>• If the test result is inconclusive, defer PrEP and follow the national algorithm until a definite test result has been obtained."], ["PrEP eligibility screening", "• Assess client for PrEP indication. This could be through an HIV exposure assessment or if the client requests PrEP<br/>• Assess for contraindications for use of the client's chosen PrEP method"], ["Counselling", "• PrEP counselling should be client-driven, based on their needs, resources, and preferences.<br/>• Counselling should include counselling on PrEP choice<br/>• For more details on counselling topics, refer to the PrEP implementation guidelines."], ["Screening for PEP eligibility and AHI", "• Assess the client for any HIV exposure in the last 72 hours; if yes, consider PEP.<br/>• Assess the client for any signs and symptoms of Acute HIV infection."], ["Additional Laboratory testing*", "• Creatinine monitoring at baseline is not required.<br/>• Hepatitis B testing is strongly encouraged for oral PrEP users. If negative, offer Hepatitis B vaccination.<br/>• Hepatitis C testing should be considered upon PrEP initiation and every 12 months thereafter, especially for MSM, people who inject drugs and people in prisons. Hepatitis C is not a contraindication for oral PrEP."], ["Screening for STIs*", "• Management of STI as per standard treatment guidelines"], ["Pregnancy testing and provision of contraceptives*", "• Should be assessed and offered as indicated"], ["Screening for mental health and substance abuse disorders*", "• Provide supportive services or referrals as needed"], ["Screening for GBV/IPV*", "• Routine enquiry of GBV and first-line support, including referral to GBV services"], ["Other services", "• Provision of or referral to VMMC services<br/>• Screening for and treatment of non-communicable diseases."], ["PrEP initiation", "• At Initiation, clients should be prescribed a single bottle/ ring and scheduled for a one-month follow-up visit.<br/>• The follow-up visit should be scheduled a few days before the pill supply will run out based on daily oral PrEP use or a week before the client should change the ring.<br/>• When possible, follow-up visits should be coordinated with visits for other services to reduce the number of times a client must return to receive services."]]],
   source_flags=["Column headings added (none in the PDF). The asterisks on several components are not explained on the page."]),
 T("tbl-2.5-renal-monitoring-oral-prep", 43, C2 + " > 2.5 Pre-exposure Prophylaxis > Follow-up appointments for PrEP users > Table 2.5 Assessing and Monitoring Renal Function for Oral PrEP users", "Table 2.5 Assessing and Monitoring Renal Function for Oral PrEP users", ["0083"],
   [r("Kidney related comorbidities", "Age", "Initiation/ Baseline", "Follow-up visit")],
   [r("No", "<30 years", "Optional", "Optional (until age 30 or if kidney-related comorbidities develop<br/>If baseline KFTs are done and CrCL <90ml/min, conduct a follow-up every 6 months"),
    r("No", "30-49 years", "Conduct creatinine test at 1 month", "If CrCl ≥90ml/min, optional (until age 50 or kidney-related comorbidities develop)<br/>If CrCL <90ml/min, screening every 6 months."),
    [C("Yes"), C("Any age"), C("Conduct creatinine test at 1 month", rs=2), C("Screening every 6 months", rs=2)],
    r("No", "50+")],
   context_before="The first follow-up appointment should be 1 month after PrEP initiation. HIV testing should be performed at every follow-up visit. Creatinine testing should be done for some clients at the one-month follow-up appointment as specified in Table 2.5. Subsequent follow-up visits should be aligned with other services, with a maximum duration of three months.",
   source_flags=["Superseded in part by the 2025 PrEP implementation guidelines (Table 17): creatinine once at or within three months of initiation and follow-up every 6-12 months for age 30-49 with CrCl 60-89, age 50+ and comorbidities; stop oral PrEP if CrCl <60 ml/min."]),
 B("box-2.6-pep-regimens", 44, C2 + " > 2.6 Post-Exposure Prophylaxis > Recommended ARV Regimen for Post-Exposure Prophylaxis", "Recommended ARV regimens for post-exposure prophylaxis (PEP)", [],
   "Adults/Adolescents ≥30kg:\n- Tenofovir (TDF)* + Lamivudine (3TC) + Dolutegravir (DTG)\n- If DTG is not available or contra-indicated, (ATV/r), DRV/r, LPV/r and RAL may be considered as an alternative 3rd drug option for PEP.\n"
   "Children 10 years and younger or <30kg:\n- Zidovudine (AZT) + 3TC is recommended as the preferred backbone regimen for PEP.\n- ABC + 3TC or TDF + 3TC can be considered as alternative regimens.\n- DTG is the preferred third drug for PEP in children as per approved dosing schedule.\n- If DTG is not available or contraindicated, (ATV/r), DRV/r, LPV/r and RAL may be considered as an alternative 3rd drug option for PEP.\n"
   "All HIV-negative individuals exposed to HIV are eligible for PEP as prescribed by any registered nurse or doctor; access PEP as early as 1 hour and within 72 hours; a three-drug regimen is preferred.\n"
   "In the event of clients presenting after sexual assault, PEP to be initiated by HCW at first contact with client even without police form (RSP88) in all health care facilities or at a community service delivery point.",
   flags=["The PDF text layer reads 'Adults/Adolescents ≥3 kg'; the printed page shows ≥30kg (used here).", "The asterisk on TDF* is not explained on the page.",
          "Children: '10 years and younger or <30kg' leaves children over 10 years but under 30 kg covered only by the weight criterion."]),
 T("tbl-2.6-pep-recommendations", 44, C2 + " > 2.6 Post-Exposure Prophylaxis > Table 2.6 Recommendations for Post-Exposure Prophylaxis", "Table 2.6 Recommendations for Post-Exposure Prophylaxis", ["0087", "0088", "0089", "0090", "0091", "0092"],
   [r("Consideration", "Recommendation")],
   [r(a, b) for a, b in [["Assessing Eligibility", "• HIV PEP should be offered and initiated as early as possible for all individuals with the exposure that has the potential for HIV transmission, within 72 hours.<br/>• Eligibility assessment should be based on the HIV status of the source of potential exposure whenever possible and may include consideration of background prevalence and local epidemiological patterns.<br/>• The following types of exposure may warrant PEP:<br/>o Body fluids: blood, blood-stained saliva, breast milk, genital secretions, cerebrospinal, amniotic, peritoneal, synovial, pericardial, or pleural fluids.<br/>o Types of exposure: Mucous membrane from sexual exposure, splashes to the eye, nose or oral cavity and parenteral exposures.<br/>o All clients should be assessed, and PEP should be offered to any client with any of the exposures as indicated above.<br/>• The exposure that does not require PEP includes:<br/>o When the exposed individual is already HIV positive<br/>o When the source of potential exposure is established to be HIV-negative unless the source has had an HIV exposure in the last 14 days and could be in the window period.<br/>o Exposure to body fluids that do not pose a significant risk: tears, non-blood-stained saliva, urine and sweat."], ["Management at initial contact", "• Counsel on risks and benefits of PEP and obtain verbal consent/assent for HIV testing.<br/>• HTS for both exposed and source individuals (where possible and applicable).<br/>• Offer PEP as soon as HIV risk exposure is established (as early as possible and within 72 hours) and if the exposed individual tests HIV-negative at baseline (if HIV testing is not available, HCWs can provide 1–2 days of PEP to cover the days until the HIV test can be performed).<br/>• If available, test women of childbearing age for pregnancy.<br/>o Offer emergency contraception for all adolescent girls and women of childbearing potential.<br/>o Copper IUCD fitted up to 5 days after unprotected sex<br/>o Levonorgestrel 1.5mg po stat or 0.75mg taken 12hrs apart<br/>• Oral contraceptive pills 4 tablets taken 12hrs apart (Microgynon/ Ovral/ Lofeminal/)<br/>• Refer to a social worker or psychologist where applicable<br/>• No specific laboratory tests are needed except:<br/>o Creatinine (if TDF-containing regimen and diabetic or hypertensive) and<br/>o Haemoglobin (if AZT-containing regimen and suspect clinical anaemia)<br/>• Assessment of hepatitis B infection status is crucial but should not be a precondition for offering HIV PEP.<br/>• If the client is Hepatitis B positive, manage according to the Hepatitis B treatment algorithm (see Annex 11.10)<br/>• If negative and not fully vaccinated: Give Hepatitis B immunoglobulin within 7 days post-exposure then Hepatitis B vaccination on Day 0 (different injection site), 1 month and 2 months. For unvaccinated children <5 years, consult a paediatrician."], ["Time of initiation", "• Initiate PEP preferably within the first hour or as soon as possible after exposure, but no later than after 72 hours.<br/>• If more than 72 hours: Conduct HTS and then repeat HTS after 8 weeks, but do not initiate ART for PEP. If confirmed HIV-positive, the client should be referred to care and treatment."], ["Duration of PEP", "• The daily dose for 28 days (dispense all 28 days of treatment at the first visit)."], ["Follow-up visits and counselling", "• Follow-up with the client at 7 days and 28 days after starting PEP. As per the client’s preference, a 7-day follow-up could be done telephonically.<br/>• At F/U visit, assess and manage side effects, provide adherence counselling and support, discuss HIV reduction, refer for trauma and mental health counselling if applicable, social support and safety and safe sex practices.<br/>• Provide results to any lab-related tests<br/>• For Hepatitis B positive clients, assess the need for ongoing Hepatitis B therapy.<br/>• Provide follow-up HIV testing 8 weeks after exposure. For HTS guidelines, see chapter 3.<br/>• Offer PrEP to clients with a high likelihood of ongoing exposure to HIV. If the HIV test is negative upon completion of 28 days with PEP, the transition to PrEP can be made without a gap.<br/>• Adherence counselling, HIV risk reduction, trauma and mental health counselling, social support and safety, and safe sex practices"], ["Other services for sexual assault and alleged sexual assault", "• Special consideration for survivors of sexual assault, particularly adolescents and children: offer supportive counselling as they are most likely to default on treatment<br/>• Offer STI prophylactic treatment for all (treat for vaginal/urethral discharge syndrome following the national STI algorithms); see National STI Algorithm for more information.<br/>• STI management and Hepatitis-B screening for penetrative cases is strongly recommended.<br/>• Alleged perpetrators are eligible for and should receive PEP services in situations of possible exposure.<br/>• Offer emergency contraception for non-pregnant women not on any contraceptive method or women not compliant/adherent to contraceptive dosing.<br/>• Document clinical evidence of assault and alleged assault and collect forensic evidence for medical-legal purposes.<br/>• Refer to the Health Sector Response to GBV - clinical management guidelines for additional details on post-rape care."], ["Repeat PEP users", "• For clients who repeatedly use PEP or clients indicating the likelihood of future potential exposure to HIV, pre-exposure prophylaxis (PrEP) should be discussed as an option."]]],
   pages=[44, 45, 46],
   source_flags=["Emergency contraception: 'Oral contraceptive pills 4 tablets taken 12hrs apart' does not say that two doses of 4 tablets are needed (Yuzpe regimen: 4 tablets of a 30 µg EE/150 µg LNG pill, repeated after 12 hours); it is also set as a main bullet rather than under the emergency-contraception options.",
                 "Hepatitis B: immunoglobulin 'within 7 days post-exposure' and vaccination at day 0, 1 month and 2 months; most guidance gives HBIG as soon as possible (ideally within 24 hours) and an accelerated schedule needs a 12-month booster."]),
 B("box-2.6.1-u-equals-u", 46, C2 + " > 2.6.1 ART for People living with HIV > Undetectable = Untransmittable (U=U)", "UNDETECTABLE = UNTRANSMITTABLE (U=U)", [],
   "When the viral load falls below 200 copies/ml, the protective effect of ART for preventing new infections approaches 100%.\nPeople taking ARVs who achieve and maintain undetectable viral load have close to zero chances of transmitting HIV to their sexual partners.\nThe U=U message has the potential to reduce stigma towards people living with HIV, increase demand for HIV testing and ART and improve adherence and this message should be well integrated in all prevention, care, and treatment programs."),
]
